+func TestShapeIndexDecodeMalformed(t *testing.T) {
+	// Generate a valid encoded index to mutate/truncate.
+	index := makeShapeIndex("0:0 | 1:1 # 0:0, 2:2 | 3:3, 4:4 # 0:0, 0:5, 5:0")
+	var validBuf bytes.Buffer
+	if err := index.Encode(&validBuf); err != nil {
+		t.Fatalf("Encode failed: %v", err)
+	}
+	validBytes := validBuf.Bytes()
+
+	// 1. All possible truncations of validBytes must return an error and not panic.
+	for i := 0; i < len(validBytes); i++ {
+		var dec ShapeIndex
+		if err := dec.Decode(bytes.NewReader(validBytes[:i])); err == nil {
+			t.Errorf("Decode of truncated input (len %d/%d) succeeded, want error", i, len(validBytes))
+		}
+	}
+
+	// 2. Single-byte corruptions across the stream must not panic.
+	for i := range validBytes {
+		corrupted := append([]byte(nil), validBytes...)
+		corrupted[i] ^= 0xff
+		var dec ShapeIndex
+		_ = dec.Decode(bytes.NewReader(corrupted))
+	}
+
+	// 3. Explicit crafted malformed inputs (oversized allocations, invalid tags, etc.).
+	malformedInputs := [][]byte{
+		{},                                      // Empty input -> EOF
+		{99, 10, 0, 0},                          // Unsupported version
